edits.newText:
export function splitKey(key: string): string[] {
  const parts: string[] = [];
  let current = '';
  let inQuotes = false;
  let quoteChar: string | null = null;
  let escape = false;

  for (let i = 0; i < key.length; i++) {
    const char = key[i];

    if (escape) {
      current += char;
      escape = false;
      continue;
    }

    if (char === '\\') {
      escape = true;
      continue;
    }

    if (inQuotes) {
      if (char === quoteChar) {
        inQuotes = false;
        quoteChar = null;
      } else {
        current += char;
      }
    } else {
      if (char === '"' || char === "'") {
        inQuotes = true;
        quoteChar = char;
      } else if (char === '.') {
        parts.push(current);
        current = '';
      } else {
        current += char;
      }
    }
  }

  if (inQuotes) {
    throw new ConfigError(`Unclosed quote in key: ${key}`);
  }

  parts.push(current);
  return parts;
}

