{
  "compilerOptions": {
    "target": "ES2022",
    "module": "ESNext",
    "moduleResolution": "bundler",
    "strict": true,
    "esModuleInterop": true,
    "skipLibCheck": true,
    "forceConsistentCasingInFileNames": true
  },
  "include": ["src/**/*"]
}

export class ConfigError extends Error {
  constructor(message: string) {
    super(message);
    this.name = 'ConfigError';
  }
}

/**
 * Splits a configuration key path into segments, respecting quotes and array brackets.
 * Dots within quoted segments are preserved as literal characters.
 *
 * @param key - The configuration key path to split (e.g. 'server.port', 'database."my.db.name".user', 'users[0].name').
 * @returns An array of string path parts representing the parsed keys and indices.
 * @throws {ConfigError} If the key path contains unclosed quotes or invalid bracket syntax.
 */
export function splitKey(key: string): string[] {
  const parts: string[] = [];
  let current = '';
  let inQuotes = false;
  let quoteChar: string | null = null;
  let escape = false;
  let inBrackets = false;
  let afterBracket = false;

  for (let i = 0; i < key.length; i++) {
    const char = key[i];

    if (escape) {
      current += char;
      escape = false;
      afterBracket = false;
      continue;
    }

    if (char === '\\') {
      escape = true;
      afterBracket = false;
      continue;
    }

    if (inQuotes) {
      if (char === quoteChar) {
        inQuotes = false;
        quoteChar = null;
      } else {
        current += char;
      }
    } else {
      if (char === '"' || char === "'") {
        inQuotes = true;
        quoteChar = char;
        afterBracket = false;
      } else if (char === '[') {
        if (inBrackets) {
          throw new ConfigError(`Nested unclosed bracket in key: ${key}`);
        }
        if (current.length > 0) {
          parts.push(current);
          current = '';
        }
        inBrackets = true;
        afterBracket = false;
      } else if (char === ']') {
        if (!inBrackets) {
          throw new ConfigError(`Unexpected closing bracket in key: ${key}`);
        }
        parts.push(current);
        current = '';
        inBrackets = false;
        afterBracket = true;
      } else if (char === '.') {
        if (afterBracket) {
          afterBracket = false;
        } else {
          parts.push(current);
          current = '';
        }
      } else {
        afterBracket = false;
        current += char;
      }
    }
  }

  if (inQuotes) {
    throw new ConfigError(`Unterminated quote in key: ${key}`);
  }

  if (inBrackets) {
    throw new ConfigError(`Unclosed bracket in key: ${key}`);
  }

  if (current.length > 0 || (!afterBracket && parts.length === 0)) {
    parts.push(current);
  }

  return parts;
}

function extractReferences(value: any): string[] {
  const refs: string[] = [];
  if (typeof value === 'string') {
    const regex = /\$\{([^}]+)\}/g;
    let match: RegExpExecArray | null;
    while ((match = regex.exec(value)) !== null) {
      refs.push(match[1].trim());
    }
  } else if (Array.isArray(value)) {
    for (const item of value) {
      refs.push(...extractReferences(item));
    }
  } else if (value !== null && typeof value === 'object') {
    for (const val of Object.values(value)) {
      refs.push(...extractReferences(val));
    }
  }
  return refs;
}

function validateCircularReferences(raw: Record<string, any>): void {
  const visitedKeys = new Set<string>();
  const resolvedKeys = new Set<string>();

  function checkCircular(key: string): void {
    if (visitedKeys.has(key)) {
      throw new ConfigError('Circular reference detected');
    }
    if (resolvedKeys.has(key)) {
      return;
    }

    visitedKeys.add(key);

    const value = raw[key];
    const refs = extractReferences(value);
    for (const ref of refs) {
      checkCircular(ref);
    }

    visitedKeys.delete(key);
    resolvedKeys.add(key);
  }

  for (const key of Object.keys(raw)) {
    checkCircular(key);
  }
}

/**
 * Parses a flat configuration dictionary with string paths into a structured nested object and array hierarchy.
 * Supports dot notation, quoted property names, and bracketed array indices.
 * Validates against circular references in configuration values.
 *
 * @param raw - A flat record of configuration keys mapped to their values.
 * @returns The structured configuration object with nested objects and arrays.
 * @throws {ConfigError} If a circular reference is detected or key paths are invalid.
 */
export function parseConfig(raw: Record<string, any>): Record<string, any> {
  validateCircularReferences(raw);

  const result: Record<string, any> = {};

  for (const [key, value] of Object.entries(raw)) {
    const parts = splitKey(key);
    let current = result;

    for (let i = 0; i < parts.length - 1; i++) {
      const part = parts[i];
      const nextPart = parts[i + 1];
      const isNextIndex = /^\d+$/.test(nextPart);

      const partKey = Array.isArray(current) && /^\d+$/.test(part) ? Number(part) : part;

      if (current[partKey] === undefined || current[partKey] === null) {
        current[partKey] = isNextIndex ? [] : {};
      }
      current = current[partKey];
    }

    const lastPart = parts[parts.length - 1];
    const finalKey = Array.isArray(current) && /^\d+$/.test(lastPart) ? Number(lastPart) : lastPart;
    current[finalKey] = value;
  }

  return result;
}
